import{_ as a,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"BlueStore, Faster + Smaller = Better - Adam Kupczyk, BM","description":"","frontmatter":{"title":"BlueStore, Faster + Smaller = Better - Adam Kupczyk, BM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Bluestore","Performance Optimization","Storage Efficiency","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/BlueStore_Faster_+_Smaller_=_Better_-_Adam_Kupczyk_BM.md","filePath":"posts/2025/BlueStore_Faster_+_Smaller_=_Better_-_Adam_Kupczyk_BM.md","lastUpdated":1780459816000}'),o={name:"posts/2025/BlueStore_Faster_+_Smaller_=_Better_-_Adam_Kupczyk_BM.md"};function i(s,e,n,_,u,p){return t(),l("div",null,[...e[0]||(e[0]=[r('<p>本次Ceph社区会议主要讨论了Bluestore存储引擎的最新技术进展、性能优化方案和未来开发路线。会议内容分为两部分：第一部分由Adam Kupczyk介绍了Bluestore的多项改进，第二部分由Ja Praash Madaka展示了其开发的性能分析工具。</p><h3 id="关键技术讨论" tabindex="-1">关键技术讨论 <a class="header-anchor" href="#关键技术讨论" aria-label="Permalink to &quot;关键技术讨论&quot;">​</a></h3><ol><li><p><strong>存储效率优化</strong></p><ul><li><strong>压缩技术改进</strong>：针对RBD场景下频繁覆写导致的压缩效率问题，提出了两种解决方案，其中方案一已经实现，可挽回10-15%的容量损失。</li><li><strong>小对象存储问题</strong>：讨论了对微小对象的特殊编码方案，但暂未实施。</li></ul></li><li><p><strong>性能优化</strong></p><ul><li><strong>RocksDB WAL格式重构</strong>：新格式合并IO操作，降低10-15%延迟，并修复了内存对齐问题。</li><li><strong>Discard操作增强</strong>：实现多线程支持，并新增监控指标。</li></ul></li><li><p><strong>元数据处理</strong></p><ul><li><strong>Onode元数据重构</strong>：采用C++ polymorphic allocators，消除blob独立存在性，减少锁竞争，提升事务处理效率。</li><li><strong>RocksDB提交优化</strong>：发现WAL刷写与memtable排序可并行化，但当前实现存在数据损坏问题。</li></ul></li><li><p><strong>内存管理</strong></p><ul><li><strong>缓存体系改进</strong>：推出与priority cache对齐的BlueFS缓存，解决内存碎片问题。</li><li><strong>分配器优化</strong>：提案实现可加载的分配器分区，解决大容量磁盘内存占用问题。</li></ul></li><li><p><strong>崩溃恢复</strong></p><ul><li><strong>并行化恢复</strong>：完全重写恢复机制，支持多线程加速，可达60倍提速。</li></ul></li></ol><h3 id="创新工具展示" tabindex="-1">创新工具展示 <a class="header-anchor" href="#创新工具展示" aria-label="Permalink to &quot;创新工具展示&quot;">​</a></h3><p>Ja Praash Madaka开发了基于perf_event_open的精准测量工具，用于硬件级PMU监控和代码块级粒度测量。</p><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>三态磁盘分配器实现</li><li>BlueFS priority cache集成</li><li>EC clone_range优化为save/restore</li><li>小对象特殊编码方案评估</li></ul><h3 id="待解决问题" tabindex="-1">待解决问题 <a class="header-anchor" href="#待解决问题" aria-label="Permalink to &quot;待解决问题&quot;">​</a></h3><ul><li>RocksDB并行提交导致的数据损坏问题</li><li>内存碎片导致的缓存抖动现象</li><li>全闪存阵列下的碎片整理策略</li></ul><h3 id="特别致谢" tabindex="-1">特别致谢 <a class="header-anchor" href="#特别致谢" aria-label="Permalink to &quot;特别致谢&quot;">​</a></h3><ul><li>Pere Diasbu：突破性重构工作（bufferlist/onode）</li><li>Mark Nelson：分层缓存概念设计</li><li>Ja Praash Madaka：多项核心优化贡献</li></ul><p>所有优化均遵循Ceph的consistency和decentralization核心原则，确保不影响现有PG分布和CRUSH algorithm行为。</p>',12)])])}const h=a(o,[["render",i]]);export{d as __pageData,h as default};
